#!/usr/bin/env python3
"""Mathematically motivated scan questions, manually selected. No transcription edits."""
from pathlib import Path
import csv,re
ROOT=Path(__file__).resolve().parents[4];O=Path(__file__).resolve().parents[1]
rows=[]
def r(cote,scan,needle,reading,alternative,evidence,weight='high',confidence='medium',f='P'):
 fn='pro/MPL_33_147-181+34_002-017_transcription.tex' if f=='P' else f'codex/{f}_transcription.tex'
 lines=(ROOT/'sources/texts'/fn).read_text().splitlines();sc=None;co=cote;hits=[]
 for no,line in enumerate(lines,1):
  m=re.search(r'\\cotefile\{(\d+)\}',line)
  if m:co=int(m.group(1))
  m=re.search(r'\\scanpage\{(\d+)\}',line)
  if m:sc=int(m.group(1))
  if sc==scan and co==cote and needle in line:hits.append(no)
 if not hits:raise ValueError((cote,scan,needle,fn))
 rows.append(dict(cote=cote,scan=f'{scan:03d}',line=f'{fn}:{hits[0]}',reading=reading,alternative=alternative,evidence=evidence,weight=weight,confidence=confidence))
